    description: "Алаг тогоруу Оросын Амар мөрний сав, Хятадын зүүн хойд хэсэгт үрждэг бөгөөд Японы Хоккайдод суурин популяци бий. Эх газрын шувуу Солонгос, Зүүн Хятадад өвөлждөг. Байгальд 3000 орчим л үлджээ. Монголд зөвхөн Дорнодын хэт зүүн хэсэгт — Халх гол, Ульз гол, Монгол Дагуурт бүртгэгдсэн бөгөөд цөөн хос заримдаа үрждэг байж магадгүй.",
